"""B33 ImageGen sheets for Ren: Ashen Eclipse (portrait, HUD icons, Eclipse Fox family, ash effect sprites). Run: python art/b33/run.py [name...]; process.py cuts them to runtime assets."""
import subprocess, os, concurrent.futures as cf
env = dict(os.environ); env['CODEX_BIN'] = r'C:\Program Files\WindowsApps\OpenAI.Codex_26.1111.2228.0_x64__2p2nqsd0c76g0\app\resources\codex.exe'
D = 'art/b33'; CON = 'art/characters/ren/f2/source/concept.png'
BLK = ("PURE BLACK (#000000) background, every element separated by generous pure-black margin, no ground, no scenery, no cast shadow, absolutely no text, letters, numbers, logo, watermark or UI. Original design. Palette: charcoal-obsidian, pale ivory ash, burnt orange embers, a little warm black-red; NOT bright red, blue or gold. ")
J = {
 'portrait': ("Pixel-art bust portrait for a game hero-select, square 1:1. Attached: (1) the design sheet whose LEFT figure (Design A) is the target look; (2) REN's Crimson Ascendant bust (same framing, pixel scale, shading and pose to match). Draw REN ASHEN ECLIPSE in the same pixel language and framing: head and shoulders, three-quarter view facing slightly right, long wild swept-back obsidian-charcoal mane with pale bone-ash tips and thin orange fissures, orange eclipse-ring eyes, scar on the cheek, one bare scarred shoulder with glowing fissure lines, torn charred jacket collar on the other shoulder, broken ash-grey wrap on the forearm near the chest. Flat solid magenta #ff00ff background. Chunky pixel blocks, no anti-aliasing, no gradients, no text, no watermark.", [CON, 'art/characters/ren/portrait/ren-px-bust-asc.png']),
 'icons': ("Eight HUD ability icons in a 4 by 2 grid, each a bold simple painted emblem inside a dark round medallion with a thin pale-ivory rim and a faint orange glow, reading clearly at 48 pixels. 1 CINDERFANG CHAIN: three clenched claw-knuckle strikes in an ascending arc. 2 ECLIPSE MAUL: a charging fox head with a streak, black disc behind with orange corona. 3 NINEFOLD RUPTURE: nine curved fox tails converging over a cracked ground ring. 4 ASHEN CATACLYSM: an eclipse core (black disc, orange corona) crushed between two fists. 5 ECLIPSE FANG: a claw gauntlet with an ember fang. 6 ECLIPSE NINE-TAILED FOX: a fox head silhouette framed by nine tails. 7 ASHEN ECLIPSE FORM: an eclipse disc over a wild mane silhouette. 8 ASH BRAND: a burning brand glyph of a fang inside a ring. Equal size, evenly spaced. " + BLK, [CON]),
 'ash_fox': ("Eclipse Nine-Tailed Fox beast sprite sheet for a premium anime action game, hand-painted 2D, crisp bold silhouettes, a massive mythic predator fox made of charcoal ash, shadow and ember, translucent with pale ivory rim light and orange glowing cracks and eyes, heat distortion hints, nine individually readable tails. SIX items in a 3 by 2 grid: 1 the fox HEAD in side view facing RIGHT, roaring, large fangs; 2 the fox front body and forelegs striding, side view facing RIGHT, cut off at the haunch; 3 NINE tails fanned out behind in a wide arc, each tail a separate readable silhouette, rooted at the left; 4 nine tails streaming long and flat to the LEFT as if in fast motion; 5 a giant spectral forepaw swiping, claws extended, side view; 6 an open jaw seen from the side with upper and lower fangs about to snap shut. " + BLK, [CON, 'public/art/fx/ren-fox/head_side0.png']),
 'ash_fx': ("Ashen Eclipse combat effect sprites for a premium anime action game, hand-painted 2D, razor-sharp shapes, readable at 120 pixels, dark cores with LIT pale ivory and orange edges so they read on dark arenas. NINE items in a 3 by 3 grid: 1 a triple parallel claw-slash mark in pale bone-ash and orange; 2 an eruption column of ash and embers rising from the ground; 3 a top-down impact crater with radial fissures glowing orange; 4 one curved fox-tail arc swipe, charcoal with a pale rim, tapering; 5 a floating burn-brand mark, a small fang glyph in a ring, burning orange; 6 a flat shock-front ring with a dark core and a bright ivory rim, seen at an oblique angle; 7 a burst of flying cinders and sparks; 8 an eclipse core: a black disc with a thin orange corona; 9 a snapping jaw bite: two opposing fang crescents closing. " + BLK, [CON]),
}
def run(n):
    pr, rf = J[n]; open(f'{D}/{n}-prompt.txt', 'w', encoding='utf-8').write(pr)
    cmd = ['python', 'scripts/gen-image.py', D, n]
    for r in rf: cmd += ['--img', r]
    r = subprocess.run(cmd, capture_output=True, text=True, env=env); return n, r.returncode, (r.stdout + r.stderr)[-140:]
if __name__ == '__main__':
    import sys
    with cf.ThreadPoolExecutor(4) as ex:
        for r in ex.map(run, sys.argv[1:] or list(J)): print(r, flush=True)
